];

// Client-mode search: keyword overlap on name and description; fall back to all tools so a weak
// query doesn't masquerade as an API limitation. The log records which path ran.
function clientSearch(args) {
  const words = JSON.stringify(args).toLowerCase().match(/[a-z]{3,}/g) ?? [];
  const hits = functions.filter((f) => words.some((w) => (f.name + " " + f.description).toLowerCase().includes(w)));
  return { matched: hits.length ? "keyword" : "fallback-all", tools: hits.length ? hits : functions };
}

const input = [];
const report = [];
for (const userText of TURNS) {
  input.push({ role: "user", content: userText });
  const turn = { user: userText, calls: [] };
  for (let step = 0; step < 8; step++) {
    const response = await openai.responses.create({
      model: MODEL,
      instructions: mcp.getInstructions() ?? undefined,
      input,
      tools,
      store: false,
      include: ["reasoning.encrypted_content"],
    });
    turn.calls.push({ requestSeq: seq, outputTypes: response.output.map((o) => o.type + (o.execution ? `(${o.execution})` : "") + (o.name ? `:${o.name}` : "")), usage: response.usage });
    input.push(...response.output);
    const pending = [];
    for (const item of response.output) {
      if (item.type === "function_call") {
        const result = await mcp.callTool({ name: item.name, arguments: JSON.parse(item.arguments || "{}") });
        pending.push({ type: "function_call_output", call_id: item.call_id, output: JSON.stringify(result.content) });
      } else if (item.type === "tool_search_call" && item.execution === "client") {
        const { matched, tools: found } = clientSearch(item.arguments);
        turn.calls.at(-1).clientSearch = { arguments: item.arguments, matched, returned: found.map((f) => f.name) };
        pending.push({ type: "tool_search_output", execution: "client", call_id: item.call_id, status: "completed", tools: found });
      }
    }
    if (!pending.length) { turn.answer = response.output_text; break; }
    input.push(...pending);
  }
  report.push(turn);
}
await mcp.close();
fs.writeFileSync(path.join(logDir, "report.json"), JSON.stringify(report, null, 2));
console.log(JSON.stringify({ logDir, report }, null, 2));

